#include "scarlett_cpu64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m;assert(m.map(0x1000,4096,7)==GuestMemory64::Fault::none);unsigned total=0;
for(unsigned n:{16u,32u})for(unsigned w:{2u,4u,8u})for(unsigned kind:{0u,1u,2u})for(unsigned form:{0u,1u,2u})for(unsigned c:{0u,1u,7u,15u,16u,31u,32u,63u,64u,255u}){if(kind==2&&w==8)continue;Cpu64State i;i.gpr[0]=0x1800;unsigned idx=w==2?1:w==4?2:3;uint64_t mask=~uint64_t(0)>>(64-w*8),v=mask-2;for(unsigned j=0;j<n;j+=w)std::memcpy((j<16?i.xmm[0].data()+j:i.ymmHigh[0].data()+j-16),&v,w);uint64_t count=c;std::memcpy(i.xmm[1].data(),&count,8);assert(m.write(0x1800,i.xmm[1])==GuestMemory64::Fault::none);unsigned group=kind==0?2:kind==1?6:4;unsigned op=(kind==0?0xd0:kind==1?0xf0:0xe0)+idx;uint8_t b=uint8_t((form==0?0xe9:0xf9)|(n==32?4:0));std::array<uint8_t,5> code{0xc5,b,uint8_t(form==0?0x70+idx:op),uint8_t(form==0?0xc0+group*8:form==1?0xd1:0x10),uint8_t(c)};assert(m.write(0x1000,code)==GuestMemory64::Fault::none);auto s=executeGuest64(m,0x1000,1,0x1900,nullptr,0,0,0,0,&i);assert(s.rip==0x1000u+(form==0?5u:4u));uint64_t expected=0;if(kind==2){expected=c>=w*8?mask:c==0?v:mask- (2u>>(c%32));if(c>=2)expected=mask;}else if(c<w*8)expected=kind==0?v>>c:(v<<c)&mask;for(unsigned j=0;j<n;j+=w){uint64_t got=0;std::memcpy(&got,j<16?s.xmm[2].data()+j:s.ymmHigh[2].data()+j-16,w);assert(got==expected);}if(n==16)for(auto x:s.ymmHigh[2])assert(x==0);++total;}
for(unsigned n:{16u,32u})for(unsigned g:{3u,7u})for(unsigned c=0;c<32;++c){Cpu64State i;for(unsigned j=0;j<16;++j){i.xmm[0][j]=j+1;i.ymmHigh[0][j]=j+33;}assert(m.write(0x1000,std::array<uint8_t,5>{0xc5,uint8_t(0xe9|(n==32?4:0)),0x73,uint8_t(0xc0+g*8),uint8_t(c)})==GuestMemory64::Fault::none);auto s=executeGuest64(m,0x1000,1,0x1900,nullptr,0,0,0,0,&i);assert(s.rip==0x1005);for(unsigned j=0;j<16;++j){int k=int(j)+(g==3?int(c):-int(c));assert(s.xmm[2][j]==(k>=0&&k<16?k+1:0));assert(s.ymmHigh[2][j]==(n==32&&k>=0&&k<16?k+33:0));}++total;}
std::cout<<"V68 tests passed: "<<total<<" cases\n";}
